// Typed approval contract (G3). The human must be able to judge this without
// opening another tab — that is the whole point of the gate.
const i = $input.first().json;
const d = i.decision || {};          // the router's decision block, computed upstream
const n = $('Normalize + classify').first().json;

// A refused diagnosis is not a diagnosis. The router answers 200 with `blocked`
// set (verify-unavailable, approval-required, mode-forbids-action, ...), and
// without this check the lane went on to ask a human to approve applying a fix
// that was never proposed. Throwing hands it to the error workflow, which says so.
if (i.blocked) {
  throw new Error(`Diagnosis for incident ${n.id} was refused by the router ` +
    `(blocked: ${i.blocked}). ${i.message || i.reason || ''} Nothing to approve.`);
}

// The router nests the dimensions under risk.dims and names the level `level`.
// This read risk.data / risk.tier, which do not exist, so every approval showed
// "none fired" and a tier of [object Object]: a gate whose reason was blank.
const risk = d.risk || {};
const dims = risk.dims || {};
const piiTypes = (d.pii?.hits || []).map((h) => h.type);
const text = (r) => (typeof r === 'string' ? r : r && typeof r.result === 'string' ? r.result : '');

return [{ json: {
  action: `Apply an automated fix to ${n.repo || 'the repo'} on branch ${n.base || 'main'}`,
  scope: d.scope || n.scope || 'unknown',
  riskTier: risk.level || n.severity || 'unknown',
  // WHICH dimensions fired, not just the resulting tier. A tier alone tells the
  // approver how worried to be; the dimensions tell them WHY, which is what they
  // are actually being asked to check.
  dimensions: [
    dims.data != null && `data=${dims.data}`,
    dims.access != null && `access=${dims.access}`,
    dims.autonomy != null && `autonomy=${dims.autonomy}`,
    piiTypes.length && `pii=${piiTypes.join('/')}`,
    Array.isArray(d.guardrails) && d.guardrails.length && `guardrails=${d.guardrails.map(g => g.type).join('/')}`,
  ].filter(Boolean).join(', ') || 'none fired',
  requester: `incident-responder (${n.severity || 'unknown'} severity, triggered by webhook)`,
  dataTouched: `${n.repo || 'repo'} working tree; verify=${n.applyVerify ? 'yes' : 'no'}`,
  preview: (text(i.result) || String(i.message || '') || '(no diagnosis returned)').slice(0, 4000),
  autoApprove: false,
} }];

const ev = $('Normalize + classify').first().json;
const fan = $('Apply fix (worktree)').first().json;
const r = (fan.results || [])[0] || {};
return [{ json: {
  severity: r.verify?.passed ? 'info' : 'warn',
  title: `Incident ${ev.id}: fix ${r.verify?.passed ? 'ready for merge' : 'NEEDS ATTENTION'}`,
  message: `${fan.review || ''}\nBranch: ${r.branch || 'n/a'} | verify: ${r.verify ? (r.verify.passed ? 'PASS' : 'FAIL') : 'not run'}\nLearning encoded to skills/. Merge remains a human act.`,
  source: 'incident-responder'
} }];

const ev = $('Normalize + classify').first().json;
const gate = $('Request approval').first().json;
return [{ json: {
  severity: 'warn',
  title: `Incident ${ev.id}: diagnosis only (fix not applied)`,
  message: `${gate.timedOut ? 'Approval timed out — default deny.' : 'Fix rejected by approver.'}\nReport remains at deliverables/${ev.id}.md.`,
  source: 'incident-responder'
} }];
